// never merge)
let wRun = [], wCur = []
for (let i = 2; i < wFaces.length; i++) {
  const k = clsArc(W[wFaces[i - 2]], W[wFaces[i - 1]], W[wFaces[i]])
  if (k === 'swing') { wCur.push(wFaces[i]); if (wCur.length > wRun.length) wRun = [...wCur] } else wCur = []
}
assert.equal(wRun.length, 12, 'THE TWELVE-SWING RUN the whole cache holds - THE RECORD')
assert.deepEqual(wRun, [353, 354, 355, 356, 357, 358, 359, 360, 361, 362, 363, 364], 'the twelve-swing run the same faces hold')

// THE ROUND TRIPS - the EIGHT mirrors the cache prices (the field's
// own four beside the W399 the 16u mirror and the W417 the 10u mirror
// and the W424 the 33u mirror and the W435 the 184u mirror THE
// BIGGEST the cache adds)
assert.equal(wr(344), SWING + '0 -> 28 (+28) -> 0 (-28)' + SWING_TAIL, 'the W344 mirror the cache shares')
assert.equal(wr(346), SWING + '0 -> 59 (+59) -> 0 (-59)' + SWING_TAIL, 'the W346 mirror the cache shares')
assert.equal(wr(367), SWING + '0 -> 10 (+10) -> 0 (-10)' + SWING_TAIL, 'the W367 mirror the cache shares')
assert.equal(wr(369), SWING + '0 -> 15 (+15) -> 0 (-15)' + SWING_TAIL, 'the W369 mirror the cache shares')
assert.equal(wr(399), SWING + '0 -> 16 (+16) -> 0 (-16)' + SWING_TAIL, 'the W399 the 16u mirror the cache adds')
assert.equal(wr(417), SWING + '10 -> 28 (+18) -> 10 (-18)' + SWING_TAIL, 'the W417 the 10u mirror the cache adds')
assert.equal(wr(424), SWING + '0 -> 33 (+33) -> 0 (-33)' + SWING_TAIL, 'the W424 the 33u mirror the cache adds')
assert.equal(wr(435), SWING + '0 -> 184 (+184) -> 0 (-184)' + SWING_TAIL, 'the W435 the 184u mirror THE BIGGEST the cache adds')

// THE GAP-CROSSING WINDOWS - the array-position read the honest gaps
// bridge (the absent 419 and the cancelled 421 the cache holds not -
// the windows the nearest-completed law prices)
assert.equal(wr(420), SWING + '10 -> 31 (+21) -> 4 (-27)' + SWING_TAIL, 'the W420 window the gap-crossing swing rides - the absent 419 the array-position read bridges')
assert.equal(wr(422), FADE + '31 -> 4 (-27) -> 0 (-4)' + FADE_TAIL, 'the W422 window the gap-crossing fade rides - the cancelled 421 the array-position read bridges')
assert.equal(wr(423), SWING + '4 -> 0 (-4) -> 33 (+33)' + SWING_TAIL, 'the W423 window the gap-crossing swing rides')

// THE WHOLE-CACHE BOUNDS' OWN LEGS - the +275 and the -289 rode ONE
// leg ONE boundary each (the same legs the field prices)
let wrises = [], wfalls = []
for (let i = 1; i < wFaces.length; i++) {
  const d = W[wFaces[i]] - W[wFaces[i - 1]]
  if (d === 275) wrises.push(`${wFaces[i - 1]}/${wFaces[i]}`)
  if (d === -289) wfalls.push(`${wFaces[i - 1]}/${wFaces[i]}`)
}
assert.equal(wrises.length, 1, 'the +275 rode ONE leg')
assert.deepEqual(wrises, ['376/377'], "the +275 rode ONE leg ONE boundary the boundary 376/377 - THE STORM'S OWN CLIMB the cache shares")
assert.equal(wfalls.length, 1, 'the -289 rode ONE leg')
assert.deepEqual(wfalls, ['377/378'], "the -289 rode ONE leg ONE boundary the boundary 377/378 - THE STORM'S OWN DRAIN the cache shares")

// THE NEWEST WINDOWS - the W440 fade and the W441/W442/W443 swings
// and the W444 swell and the W445 swing (MY WORD'S OWN FIRST LIVE
// READ the nearest-completed law holds)
assert.equal(wr(440), FADE + '84 -> 56 (-28) -> 1 (-55)' + FADE_TAIL, "the W440 window the fade rides - the floor's own newest seat")
assert.equal(wr(441), SWING + '56 -> 1 (-55) -> 40 (+39)' + SWING_TAIL, 'the W441 window the swing rides')
assert.equal(wr(442), SWING + '1 -> 40 (+39) -> 9 (-31)' + SWING_TAIL, 'the W442 window the swing rides')
assert.equal(wr(443), SWING + '40 -> 9 (-31) -> 50 (+41)' + SWING_TAIL, 'the W443 window the swing rides')
assert.equal(wr(444), SWELL + '9 -> 50 (+41) -> 191 (+141)' + SWELL_TAIL, 'the W444 window the swell rides')
assert.equal(wr(445), SWING + '50 -> 191 (+141) -> 104 (-87)' + SWING_TAIL, "the W445 window the swing rides - MY WORD'S OWN FIRST LIVE READ")

// THE REUSE LAW battery - transitCensus's own launches.n cell the
// fold rides (the launch's own count rides whole, the stall family
// and the shore pins and the swim releases never ride - the v0.976.60
// word's own seat beside, the lanes never merge)
const lcOf = (ls) => transitCensus(ls).launches.n
const L = (s) => lcOf(s.split('\n'))
assert.equal(L('F2 [F2] water: transit toward known land (oak_log) at [-122,417] d=51'), 1, 'the launch rides')
assert.equal(L('F9 [F9] water: transit toward known land (sand) at [10,20] d=0'), 1, 'the zero-distance launch rides the same skin')
assert.equal(L('F3 [F3] water: transit stalled (d=5 after 3 passes - the walls own this swim; the release takes over)'), 0, 'the stall family never rides - the v0.976.60 word own seat')
assert.equal(L('F3 [F3] water: shore pinned (r=4 after 2 passes - the shoreline owns this swim; the release takes over)'), 0, 'the shore pin never rides')
assert.equal(L('F3 [F3] water: shore transit stalled (r=3 after 4 passes - the walls own this swim; the release takes over)'), 0, 'the shore transit stall never rides')
assert.equal(L('F5 [F5] water: transit toward known land (oak_log) at [-122,417]'), 0, 'the torn tail never rides')
assert.equal(L('F5 water: transit toward known land (oak_log) at [-122,417] d=51'), 0, 'the bare-prefix form never rides')
assert.equal(L('F5 [F6] water: transit toward known land (oak_log) at [-122,417] d=51'), 0, 'the bracket-mismatched form never rides')
assert.equal(L('water: transit toward known land (oak_log) at [-122,417] d=51'), 0, 'the bare form never rides')
assert.equal(L('F2 [F2] water: transit toward known land (oak_log) at [-122,417] d=-51'), 0, 'the negative distance never rides')
assert.equal(L('F2 [F2] water: transit toward known land (oak_log) at [-122,417] d=51.5'), 0, 'the fractional distance never rides')
assert.equal(L('F2 [F2] water: transit toward known land (oak_log) at [-122] d=51'), 0, 'the torn coords never ride')
assert.equal(L(''), 0, 'the empty line never rides')
assert.equal(L('F2 [F2] water: transit toward known land (oak_log) at [-122,417] d=51\nF9 [F9] water: transit toward known land (gravel) at [5,7] d=12'), 2, 'the launches the count rides whole')
assert.equal(L('F2 [F2] water: transit toward known land (oak_log) at [-122,417] d=51\nF2 [F2] water: transit stalled (d=5 after 3 passes - the walls own this swim; the release takes over)'), 1, 'the stall row never rides even beside the launch')

// THE FENCE - the fold proves itself or the word prices nothing
assert.equal(transitLaunchTrendRow(null), null, 'the null fold prices nothing')
assert.equal(transitLaunchTrendRow(undefined), null, 'the undefined fold prices nothing')
assert.equal(transitLaunchTrendRow('junk'), null, 'the junk fold prices nothing')
assert.equal(transitLaunchTrendRow([]), null, 'the array fold prices nothing')
assert.equal(transitLaunchTrendRow({}), null, 'the faceless fold prices nothing')
assert.equal(transitLaunchTrendRow({ back: { launches: 1 }, prev: { launches: 2 } }), null, 'the two-faced fold prices nothing')
assert.equal(transitLaunchTrendRow({ back: { launches: -1 }, prev: { launches: 2 }, cur: { launches: 3 } }), null, 'the negative face prices nothing')
assert.equal(transitLaunchTrendRow({ back: { launches: 1.5 }, prev: { launches: 2 }, cur: { launches: 3 } }), null, 'the fractional face prices nothing')
assert.equal(transitLaunchTrendRow({ back: { launches: '1' }, prev: { launches: 2 }, cur: { launches: 3 } }), null, 'the string face prices nothing')
assert.equal(transitLaunchTrendRow({ back: { launches: 1 }, prev: { launches: 1 }, cur: { launches: 1 }, extra: 'key' }), null, 'the held step prices the honest silence - the extra key never rejected')
assert.equal(transitLaunchTrendRow({ back: { launches: 0 }, prev: { launches: 0 }, cur: { launches: 0 }, extra: 'key' }), null, 'the lawful zero face rides the fence - the held zero the honest silence')
assert.equal(transitLaunchTrendConsistent({ back: { launches: 0 }, prev: { launches: 3 }, cur: { launches: 7 }, junk: 1 }), true, 'the fence the extra keys never rejects')
assert.equal(transitLaunchTrendConsistent(null), false, 'the null fold never proves itself')
assert.equal(transitLaunchTrendConsistent({ back: { launches: 0 }, prev: { launches: 3 } }), false, 'the two-faced fold never proves itself')

// THE BYTE-PIN - the tail rides byte-exact (the seat the family's own
// enumeration holds)
const row = transitLaunchTrendRow({ back: { launches: 1 }, prev: { launches: 3 }, cur: { launches: 2 } })
assert.ok(row.startsWith(HEAD), 'the head byte-exact')
assert.ok(row.endsWith('co-existence by seat never by duplication)'), 'the tail closes the seat law')
assert.ok(row.includes(TAIL), 'the tail rides byte-exact')

